import AVFoundation

/// The two sounds Cadence makes while it is open: a soft tick when a set is logged and a chime
/// when rest is over. They play under whatever the athlete is listening to, keep quiet with the
/// ring switch on silent, and stop altogether with Settings, Sounds off. In the background the
/// rest-over notification rings the same chime. The files are generated by `scripts/generate_sounds.py`.
@MainActor
enum SoundEffects {
    enum Sound: String, CaseIterable {
        case setLogged = "set-logged"
        case restOver = "rest-over"
    }

    nonisolated static let enabledKey = "soundsEnabled"

    static var isEnabled: Bool { UserDefaults.standard.object(forKey: enabledKey) as? Bool ?? true }

    private static var players: [Sound: AVAudioPlayer] = [:]

    /// Loads both sounds at launch, so the first set logged ticks with no delay.
    static func prepare() {
        // Ambient mixes with other audio rather than pausing it, and follows the ring switch.
        try? AVAudioSession.sharedInstance().setCategory(.ambient)
        for sound in Sound.allCases {
            guard let url = Bundle.main.url(forResource: sound.rawValue, withExtension: "caf"),
                  let player = try? AVAudioPlayer(contentsOf: url) else { continue }
            player.prepareToPlay()
            players[sound] = player
        }
    }

    static func play(_ sound: Sound) {
        guard isEnabled, let player = players[sound] else { return }
        player.currentTime = 0
        player.play()
    }
}
